82:
SELECT "gsoffered" AS grade_span_offered
FROM schools
WHERE "longitude" = (SELECT MAX("longitude") FROM schools);

323:
SELECT DISTINCT m."label"
FROM "molecule" m
WHERE m."molecule_id" = 'TR000';

239:
SELECT COUNT(DISTINCT "bond_id") AS connections_count
FROM "connected"
WHERE "atom_id" LIKE 'TR%_19' OR "atom_id2" LIKE 'TR%_19';

290:
SELECT DISTINCT a."element"
FROM "atom" a
WHERE a."molecule_id" = 'TR151'
  AND a."element" IN (
    'cl', 'br', 'f', 'i', 'pb', 'te', 'sn'
  );

355:
SELECT DISTINCT "keywords"
FROM "cards"
WHERE "name" LIKE '%Angel of Mercy%';

509:
SELECT "id"
FROM "sets"
WHERE "basesetsize" = (SELECT MAX(CAST("basesetsize" AS BIGINT)) FROM "sets");

588:
SELECT COUNT(*) AS total_comments
FROM "comments"
WHERE "userid"::BIGINT = 13;

745:
SELECT DISTINCT p."id"
FROM "publisher" p
WHERE p."publisher_name" LIKE '%Star Trek%';

747:
SELECT COUNT(*) AS total_number
FROM "superhero"
WHERE "full_name" IS NULL;

1377:
SELECT COUNT(DISTINCT "member_id") AS count
FROM "member"
WHERE LOWER("position") LIKE '%president%';
